def _filter_invoices(invoices: list[dict], allowed_statuses: set[str]) -> list[dict]:
    """Stage 1: return invoices with valid status, non-empty region, and integer amount."""
    result = []
    for invoice in invoices:
        filter_status = invoice.get("status") in allowed_statuses
        filter_region = isinstance(invoice.get("region"), str) and len(invoice.get("region", "")) > 0
        filter_amount = isinstance(invoice.get("amount_cents"), int)
        if filter_status and filter_region and filter_amount:
            result.append(invoice)
    return result


def _accumulate_buckets(invoices: list[dict]) -> dict[str, dict]:
    """Stage 2: group by region, accumulate counts and totals."""
    buckets: dict[str, dict] = {}
    for invoice in invoices:
        region = invoice["region"]
        cents = invoice["amount_cents"]
        if region not in buckets:
            buckets[region] = {"item_count": 0, "cents_total": 0}
        buckets[region]["item_count"] += 1
        buckets[region]["cents_total"] += cents
    return buckets


def _emit_records(buckets: dict[str, dict]) -> list[dict]:
    """Stage 3: produce sorted legacy records with required keys."""
    output = []
    for region_key in sorted(buckets.keys()):
        output.append({
            "bucket_code": region_key,
            "item_count": buckets[region_key]["item_count"],
            "cents_total": buckets[region_key]["cents_total"],
        })
    return output


def summarize_invoices(invoices: list[dict], *, include_unpaid: bool = False) -> list[dict]:
    allowed_statuses = {"paid", "unpaid"} if include_unpaid else {"paid"}
    filtered = _filter_invoices(invoices, allowed_statuses)
    buckets = _accumulate_buckets(filtered)
    return _emit_records(buckets)

