    if not isinstance(invoices, list):
        raise TypeError(
            f"summarize_invoices expects a list, got {type(invoices).__name__!r}"
        )
    if not isinstance(include_unpaid, bool):
        raise TypeError(
            f"include_unpaid must be a bool, got {type(include_unpaid).__name__!r}"
        )
    for idx, item in enumerate(invoices):
        if not isinstance(item, dict):
            raise TypeError(
                f"Each invoice must be a dict; element at index {idx} is "
                f"{type(item).__name__!r}"
            )

    allowed_statuses = {"paid", "unpaid"} if include_unpaid else {"paid"}
    filtered = _filter_invoices(invoices, allowed_statuses)
    buckets = _accumulate_buckets(filtered)
    return _emit_records(buckets)

